def assess(w,k,marks,reasons=None):
    x=json.loads(json.dumps(w)); grades=[]
    for j,pts in enumerate(marks):
        s=M[k]['examData']['scoring']['steps'][j//3]
        pieces=re.split(r'Kriterium [123] \(2 BE\): ',s['description'])[1:]
        assert len(pieces)==3
        exact=pieces[j%3].strip()
        reason=(reasons[j] if reasons else ('Die vollständige eigene Antwort zeigt beide im Originalkriterium genannten Teilbeiträge inhaltlich richtig; ihre konkrete fachliche Darstellung ist unten vollständig gebunden.' if pts==2 else 'In dieser eigenen Antwort ist nur ein Teil des unten vollständig gebundenen Originalkriteriums tragfähig; die explizite Gesamtabsenz betrifft die im separaten Befund genannte Kernleistung, nicht alle vorhandenen Teilbeiträge.' if pts==1 else 'Die eigene Antwort lässt dieses Originalkriterium aus oder verfehlt es ausdrücklich; vorhandene andere Kernleistungen ersetzen es nicht.'))
        grades.append({'criterionId':f'{s["id"]}.c{j%3+1}','maximum':2,'pointsAwarded':pts,'actualWholeOriginalScoringStep':s,'actualSpecificCriterionVerbatim':exact,'wholeOwnAnswerWitness':w['wholeOwnFourTaskAnswers'][j//3]['answer'],'independentManualRationale':reason})
    raw=sum(marks); cap=w['actualPublishedCapAppliedOnlyToGenuineWholeAbsence'];final=min(14,raw) if cap else raw
    x['whole12IndependentManualCriterionGrades']=grades;x['rawPoints']=raw;x['finalPoints']=final;x['result']='PASS' if final>=15 else 'FAIL';x['assessmentStage']='actual original-rubric precision successor; old provisional grades immutable'
    return x
